const body = $input.first().json.body;

// Mapeo de tipos de tarea a agentes
const taskToAgentMap = {
  // Content tasks
  'write_blog': 'content-002',
  'write_whitepaper': 'content-003',
  'write_case_study': 'content-004',
  'publish_content': 'content-005',

  // Social tasks
  'create_linkedin_post': 'social-001',
  'create_twitter_thread': 'social-002',
  'write_youtube_script': 'social-003',
  'create_short_video': 'social-004',
  'analyze_engagement': 'social-006',
  'schedule_posts': 'social-007',

  // Demand Gen tasks
  'manage_meta_ads': 'demandgen-002',
  'manage_google_ads': 'demandgen-003',
  'manage_linkedin_ads': 'demandgen-004',
  'analyze_ad_performance': 'demandgen-005',
  'analyze_budget_pacing': 'demandgen-006',

  // SEO tasks
  'keyword_research': 'seo-001',
  'analyze_backlinks': 'seo-002',
  'technical_seo_audit': 'seo-003',
  'track_rankings': 'seo-004',

  // Brand tasks
  'design_ad_creative': 'brand-001',
  'build_landing_page': 'brand-002',
  'organize_assets': 'brand-003',

  // Ops tasks
  'write_newsletter': 'ops-002',
  'build_nurture_campaign': 'ops-003',
  'clean_email_list': 'ops-004',
};

// Mapeo de agentes a endpoints de n8n
const agentEndpoints = {
  'content-002': '/webhook/agent/content-002/execute',
  'content-003': '/webhook/agent/content-003/execute',
  'content-004': '/webhook/agent/content-004/execute',
  'content-005': '/webhook/agent/content-005/execute',
  'social-001': '/webhook/agent/social-001/execute',
  'social-002': '/webhook/agent/social-002/execute',
  'social-003': '/webhook/agent/social-003/execute',
  'social-004': '/webhook/agent/social-004/execute',
  'social-006': '/webhook/agent/social-006/execute',
  'social-007': '/webhook/agent/social-007/execute',
  'demandgen-002': '/webhook/agent/demandgen-002/execute',
  'demandgen-003': '/webhook/agent/demandgen-003/execute',
  'demandgen-004': '/webhook/agent/demandgen-004/execute',
  'demandgen-005': '/webhook/agent/demandgen-005/execute',
  'demandgen-006': '/webhook/agent/demandgen-006/execute',
  'seo-001': '/webhook/agent/seo-001/execute',
  'seo-002': '/webhook/agent/seo-002/execute',
  'seo-003': '/webhook/agent/seo-003/execute',
  'seo-004': '/webhook/agent/seo-004/execute',
  'brand-001': '/webhook/agent/brand-001/execute',
  'brand-002': '/webhook/agent/brand-002/execute',
  'brand-003': '/webhook/agent/brand-003/execute',
  'ops-002': '/webhook/agent/ops-002/execute',
  'ops-003': '/webhook/agent/ops-003/execute',
  'ops-004': '/webhook/agent/ops-004/execute',
};

const taskType = body.taskType;
const targetAgent = body.targetAgent || taskToAgentMap[taskType];

if (!targetAgent) {
  throw new Error(`No agent found for task type: ${taskType}`);
}

const endpoint = agentEndpoints[targetAgent];

if (!endpoint) {
  throw new Error(`No endpoint configured for agent: ${targetAgent}`);
}

return {
  targetAgent,
  endpoint,
  taskType,
  payload: body
};

