parameters.jsCode:
const agentResult = $input.first().json;
const routeInfo = $node['Route Task to Agent'].json;
const taskInfo = $node['Create Task in Convex'].json;

// Verificar si hay handoff pendiente
const handoffRules = {
  'write_blog': [
    { nextTask: 'publish_content', condition: 'always' },
    { nextTask: 'create_linkedin_post', condition: 'always' },
    { nextTask: 'create_twitter_thread', condition: 'always' }
  ],
  'keyword_research': [
    { nextTask: 'write_blog', condition: 'keywords_found' }
  ],
  'publish_content': [
    { nextTask: 'schedule_posts', condition: 'always' }
  ]
};

const rules = handoffRules[routeInfo.taskType] || [];
const handoffs = [];

for (const rule of rules) {
  if (rule.condition === 'always' || agentResult[rule.condition]) {
    handoffs.push({
      taskType: rule.nextTask,
      parentTaskId: taskInfo.value.id,
      input: {
        ...agentResult.output,
        sourceTaskType: routeInfo.taskType
      }
    });
  }
}

return {
  success: true,
  taskId: taskInfo.value.taskId,
  agent: routeInfo.targetAgent,
  result: agentResult,
  handoffs: handoffs
};

